// --- Safe Results ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ToxError {
    AvAnswer(AvAnswerError),
    AvBitRateSet(AvBitRateSetError),
    AvCall(AvCallError),
    AvCallControl(AvCallControlError),
    AvNew(AvNewError),
    AvSendFrame(AvSendFrameError),
    Bootstrap(BootstrapError),
    ConferenceById(ConferenceByIdError),
    ConferenceDelete(ConferenceDeleteError),
    ConferenceGetType(ConferenceGetTypeError),
    ConferenceInvite(ConferenceInviteError),
    ConferenceJoin(ConferenceJoinError),
    ConferenceNew(ConferenceNewError),
    ConferencePeerQuery(ConferencePeerQueryError),
    ConferenceSendMessage(ConferenceSendMessageError),
    ConferenceSetMaxOffline(ConferenceSetMaxOfflineError),
    ConferenceTitle(ConferenceTitleError),
    Decryption(DecryptionError),
    Encryption(EncryptionError),
    EventsIterate(EventsIterateError),
    FileById(FileByIdError),
    FileControl(FileControlError),
    FileGet(FileGetError),
    FileSeek(FileSeekError),
    FileSend(FileSendError),
    FileSendChunk(FileSendChunkError),
    FriendAdd(FriendAddError),
    FriendByPublicKey(FriendByPublicKeyError),
    FriendCustomPacket(FriendCustomPacketError),
    FriendDelete(FriendDeleteError),
    FriendGetLastOnline(FriendGetLastOnlineError),
    FriendGetPublicKey(FriendGetPublicKeyError),
    FriendQuery(FriendQueryError),
    FriendSendMessage(FriendSendMessageError),
    GetPort(GetPortError),
    GetSalt(GetSaltError),
    GroupById(GroupByIdError),
    GroupDisconnect(GroupDisconnectError),
    GroupInviteAccept(GroupInviteAcceptError),
    GroupInviteFriend(GroupInviteFriendError),
    GroupIsConnected(GroupIsConnectedError),
    GroupJoin(GroupJoinError),
    GroupKickPeer(GroupKickPeerError),
    GroupLeave(GroupLeaveError),
    GroupNew(GroupNewError),
    GroupPeerQuery(GroupPeerQueryError),
    GroupSelfNameSet(GroupSelfNameSetError),
    GroupSelfQuery(GroupSelfQueryError),
    GroupSelfStatusSet(GroupSelfStatusSetError),
    GroupSendCustomPacket(GroupSendCustomPacketError),
    GroupSendCustomPrivatePacket(GroupSendCustomPrivatePacketError),
    GroupSendMessage(GroupSendMessageError),
    GroupSendPrivateMessage(GroupSendPrivateMessageError),
    GroupSetIgnore(GroupSetIgnoreError),
    GroupSetPassword(GroupSetPasswordError),
    GroupSetPeerLimit(GroupSetPeerLimitError),
    GroupSetPrivacyState(GroupSetPrivacyStateError),
    GroupSetRole(GroupSetRoleError),
    GroupSetTopicLock(GroupSetTopicLockError),
    GroupSetVoiceState(GroupSetVoiceStateError),
    GroupStateQuery(GroupStateQueryError),
    GroupTopicSet(GroupTopicSetError),
    IterateOptionsNew(IterateOptionsNewError),
    KeyDerivation(KeyDerivationError),
    New(NewError),
    OptionsNew(OptionsNewError),
    SetInfo(SetInfoError),
    SetTyping(SetTypingError),
    Failed,
    InvalidString(std_ffi::NulError),
}

impl error::Error for ToxError {}
impl fmt::Display for ToxError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:?}", self)
    }
}

pub type Result<T> = std::result::Result<T, ToxError>;
